files.examples/01_explain_vs_analyze.sql:
-- LEARN(sql.indexes.btree): EXPLAIN predicts, EXPLAIN ANALYZE runs and measures.
CREATE TABLE orders (
  id          bigint PRIMARY KEY,
  customer_id int NOT NULL,
  total       numeric(10,2) NOT NULL
);
INSERT INTO orders
SELECT g, g % 1000 + 1, g % 500 + 0.99 FROM generate_series(1, 20000) AS g;
ANALYZE orders;

-- No index on customer_id: the only plan is to read every row.
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders WHERE customer_id = 42;

CREATE INDEX orders_customer_id ON orders (customer_id);

-- Same query, new plan. Still a prediction: nothing has run.
EXPLAIN (COSTS OFF)
SELECT id, total FROM orders WHERE customer_id = 42;

-- ANALYZE executes it: real row counts, and the pages it touched.
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT id, total FROM orders WHERE customer_id = 42;

-- Plain EXPLAIN of a DELETE only plans it...
EXPLAIN (COSTS OFF)
DELETE FROM orders WHERE customer_id = 42;
-- ...with ANALYZE it executes: this DELETE deletes.
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
DELETE FROM orders WHERE customer_id = 42;
SELECT count(*) AS orders_left FROM orders WHERE customer_id = 42;

files.examples/02_btree_depth.sql:
-- Three tables that differ only in size. Each primary key is a B-tree index.
CREATE TABLE small  (id int PRIMARY KEY, pad text);
CREATE TABLE medium (id int PRIMARY KEY, pad text);
CREATE TABLE large  (id int PRIMARY KEY, pad text);
INSERT INTO small  SELECT g, 'row ' || g FROM generate_series(1, 100) AS g;
INSERT INTO medium SELECT g, 'row ' || g FROM generate_series(1, 10000) AS g;
INSERT INTO large  SELECT g, 'row ' || g FROM generate_series(1, 200000) AS g;

-- Warm-up: plan each lookup once, so the measurements below count only
-- the pages the lookup itself visits, not the planner's catalog reads.
SELECT s.pad, m.pad, l.pad
FROM small s, medium m, large l
WHERE s.id = 42 AND m.id = 42 AND l.id = 42;

-- One page per tree level, plus one heap page for the row itself.
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT pad FROM small WHERE id = 42;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT pad FROM medium WHERE id = 42;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT pad FROM large WHERE id = 42;

-- A range descends once, then walks the linked leaf pages sideways.
EXPLAIN (COSTS OFF)
SELECT pad FROM large WHERE id BETWEEN 1000 AND 1999;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT pad FROM large WHERE id BETWEEN 1000 AND 1999;

files.examples/03_index_ignored.sql:
-- amount is spread over the table in no particular order, like most columns.
CREATE TABLE payments (
  id     bigint PRIMARY KEY,
  amount int NOT NULL,
  note   text NOT NULL
);
INSERT INTO payments
SELECT g, (g * 7919) % 1000, 'payment ' || g FROM generate_series(1, 20000) AS g;
CREATE INDEX payments_amount ON payments (amount);
ANALYZE payments;

-- 1% of the rows: the index pays off.
EXPLAIN (COSTS OFF)
SELECT max(note) FROM payments WHERE amount < 10;

-- 90% of the rows: the index exists, and the planner ignores it.
EXPLAIN (COSTS OFF)
SELECT max(note) FROM payments WHERE amount < 900;

-- Measure the planner's choice...
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT max(note) FROM payments WHERE amount < 900;

-- ...against the index it rejected. SET LOCAL lasts until the transaction ends.
SET LOCAL enable_seqscan = off;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT max(note) FROM payments WHERE amount < 900;

SET LOCAL enable_bitmapscan = off;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT max(note) FROM payments WHERE amount < 900;
